action.command:
cd /workspace
perl -0pi -e 's/  arsort\(\$required\);
  arsort\(\$non_required\);

  \$batch_builder = new BatchBuilder\(\);/  arsort(\$required);
  arsort(\$non_required);

  \$debug_all = \$required + \$non_required;
  \$debug_out = [];
  foreach (array_keys(\$debug_all) as \$dm) { \$debug_out[] = \$dm . "(w" . \$debug_all[\$dm] . ")"; }
  file_put_contents("/tmp/batch_all.log", implode("\n", \$debug_out) . "\n=== GROUPS ===\n", FILE_APPEND);

  \$batch_builder = new BatchBuilder();/' web/core/includes/install.core.inc
perl -0pi -e 's|file_put_contents\("/var/www/html/\.batch_debug\.log", json_encode\(\$modules\) \. "\n", FILE_APPEND\);|file_put_contents("/tmp/batch_groups.log", json_encode(\$modules) . "\n", FILE_APPEND);|' web/core/includes/install.core.inc
grep -n "batch_all.log\|batch_groups.log" web/core/includes/install.core.inc
php -l web/core/includes/install.core.inc 2>&1 | head -2
